def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    prefix_length = len(prefix)
    for i in range(len(s) - prefix_length + 1):
        if s[i:i + prefix_length] == prefix:
            # Find the suffix anywhere after the current prefix ends.
            if s.find(suffix, i + prefix_length) != -1:
                return True
    return False

