def findValidPair(s: str) -> str:
    counts = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:  # Check if adjacent digits are different
            d1, d2 = s[i], s[i + 1]
            if counts[d1] == int(d1) and counts[d2] == int(d2):
                return d1 + d2
    return ""

def maxDifference(s: str) -> int:
    from collections import Counter
    frequency = Counter(s)
    odd_freqs = [count for count in frequency.values() if count % 2 != 0]
    even_freqs = [count for count in frequency.values() if count % 2 == 0]
    return max(odd_freqs) - min(even_freqs)

