def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp_table = [[0] * n for _ in range(n)]
    max_length = 0

    for i in range(n):
        for j in range(i):
            dp_table[i][j] = 2  # Minimum length for a valid pair
            for k in range(j):
                if abs(nums[i] - nums[j]) <= abs(nums[j] - nums[k]):
                    dp_table[i][j] = max(dp_table[i][j], dp_table[j][k] + 1)
            max_length = max(max_length, dp_table[i][j])

    return max_length

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)
    for i in range(len(s)):
        if marked[i]:
            continue
        mirror = chr(ord('a') + (ord('z') - ord(s[i])))
        for j in range(i - 1, -1, -1):
            if s[j] == mirror and not marked[j]:
                marked[i] = True
                marked[j] = True
                score += i - j
                break
    return score

