def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Initialize starting point
    if coins[0][0] < 0:
        dp[0][0][1] = 0  # Neutralize if starting cell is a robber

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k indicates number of robbers neutralized
                if i == 0 and j == 0:
                    continue  # Skip starting cell
                value = coins[i][j]
                from_top = -float('inf')
                if i > 0:
                    # Option 1: Don't neutralize current cell
                    from_top = dp[i-1][j][k] + value
                    # Option 2: Neutralize current cell (if it's a robber)
                    if value < 0 and k > 0:
                        from_top = max(from_top, dp[i-1][j][k-1])
                from_left = -float('inf')
                if j > 0:
                    # Option 1: Don't neutralize current cell
                    from_left = dp[i][j-1][k] + value
                    # Option 2: Neutralize current cell (if it's a robber)
                    if value < 0 and k > 0:
                        from_left = max(from_left, dp[i][j-1][k-1])
                dp[i][j][k] = max(from_top, from_left)

    return max(dp[m-1][n-1])  # Return the maximum profit at the bottom-right corner

