import collections

def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    edges.sort(key=lambda x: x[2])  # Sort edges by weight
    low, high = 1, 10**6  # The weights are in the range [1, 10^6]

    def canAchieve(max_weight: int) -> bool:
        graph = collections.defaultdict(list)
        out_degree_count = collections.defaultdict(int)
        for u, v, w in edges:
            if w > max_weight:
                break  # Edges are sorted, no need to check further
            if out_degree_count[u] < threshold:
                out_degree_count[u] += 1
                graph[v].append(u)  # Build reversed graph

        visited = [False] * n
        queue = collections.deque([0])  # Start BFS from node 0
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:  # Check incoming edges to 0
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return all(visited[i] for i in range(1, n))  # Check if all nodes can reach 0

    while low < high:
        mid = (low + high) // 2
        if canAchieve(mid):
            high = mid
        else:
            low = mid + 1

    return low if canAchieve(low) else -1

