def minCost(n: int, cost: List[List[int]]) -> int:
    # DP table
    dp = [[float('inf')] * 3 for _ in range(3)]

    # Initial fill based on the first house
    for j in range(3):
        dp[0][j] = cost[0][j]

    for i in range(1, n // 2 + 1):
        new_dp = [[float('inf')] * 3 for _ in range(3)]
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:  # Ensure the equidistant colors are different
                    for prev_c1 in range(3):
                        if c1 != prev_c1:  # No adjacent same colors
                            new_dp[c1][c2] = min(new_dp[c1][c2], dp[prev_c1][(prev_c1 + c2) % 3] + cost[i][c1] + cost[n - 1 - i][c2])
        dp = new_dp

    # Finally, we fetch the minimum cost from the last DP table
    return min(min(dp[c1][c2] for c2 in range(3)) for c1 in range(3))

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    # Sort events by timestamp, prioritizing OFFLINE events over MESSAGE events
    events.sort(key=lambda x: (int(x[1]), x[0] == "MESSAGE"))

    for event in events:
        event_type, timestamp, detail = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(detail)
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Process offline users coming back online
            for user_id in range(numberOfUsers):
                if offline_until[user_id] <= timestamp:
                    online_status[user_id] = True

            for word in detail.split():
                if word == "HERE":
                    for i in range(numberOfUsers):
                        if online_status[i]:
                            mentions[i] += 1
                elif word == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif word.startswith("id"):
                    try:
                        user_id = int(word[2:])
                        if 0 <= user_id < numberOfUsers:
                            mentions[user_id] += 1
                    except ValueError:
                        pass  # Ignore malformed ids

    return mentions
